const input = $input.first().json;
const body = input.body;
const headerKey = input.headers?.['idempotency-key'];
const allowedTests = new Set(['ist', 'papi', 'rmib', 'kraepelin', 'dass21']);

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('invalid_request_body');
}

const validKey = typeof body.idempotency_key === 'string'
  && /^[0-9A-HJKMNP-TV-Z]{26}$/.test(body.idempotency_key)
  && headerKey === body.idempotency_key;
const validPhone = typeof body.recipient?.phone === 'string'
  && /^\+?[0-9]{8,15}$/.test(body.recipient.phone);
const validTestNumber = typeof body.credentials?.test_number === 'string'
  && /^[A-Z0-9-]{1,32}$/.test(body.credentials.test_number);
const validEntitlements = Array.isArray(body.entitlements)
  && body.entitlements.length > 0
  && body.entitlements.length === new Set(body.entitlements).size
  && body.entitlements.every((value) => typeof value === 'string' && allowedTests.has(value));

if (body.event !== 'participant.activation'
  || body.schema_version !== 1
  || !validKey
  || !validPhone
  || !validTestNumber
  || !validEntitlements) {
  throw new Error('invalid_participant_activation_contract');
}

const phoneDigits = body.recipient.phone.replace(/\D/g, '');
const testLabels = body.entitlements.map((value) => value.toUpperCase());
const canonical = JSON.stringify({
  event: body.event,
  schema_version: body.schema_version,
  idempotency_key: body.idempotency_key,
  phone: body.recipient.phone,
  test_number: body.credentials.test_number,
  entitlements: body.entitlements,
});

return [{
  json: {
    event: body.event,
    idempotency_key: body.idempotency_key,
    request_canonical: canonical,
    claim_token: $execution.id,
    chat_id: `${phoneDigits}@c.us`,
    message: [
      'Pembayaran Anda telah terverifikasi.',
      `Nomor tes: ${body.credentials.test_number}`,
      `Tes aktif: ${testLabels.join(', ')}`,
      '',
      'Simpan nomor tes ini dan jangan membagikannya kepada pihak lain.',
    ].join('\n'),
  },
}];
